input.command:
cd E:/runebench/rs-sdk && bun -e '
const fs=require("fs");
const dir="wiki/npcs";
const rows=[];
for(const f of fs.readdirSync(dir)){
  const t=fs.readFileSync(dir+"/"+f,"utf8");
  const lvl=t.match(/Combat Level\*\*\s*\|\s*([0-9]+)/);
  const hp=t.match(/Hitpoints\*\*\s*\|\s*([0-9]+)/);
  const sd=t.match(/Slash Defence\s*\|\s*(-?[0-9]+)/);
  const cd=t.match(/Crush Defence\s*\|\s*(-?[0-9]+)/);
  const atk=t.match(/Attack Bonus\s*\|\s*(-?[0-9]+)/);
  const str=t.match(/Strength Bonus\s*\|\s*(-?[0-9]+)/);
  if(!lvl||!hp) continue;
  rows.push({name:f.replace(".md",""),lvl:+lvl[1],hp:+hp[1],sd:sd?+sd[1]:null,cd:cd?+cd[1]:null,atk:atk?+atk[1]:null,str:str?+str[1]:null});
}
rows.sort((a,b)=>b.lvl-a.lvl);
console.log("HIGHEST LEVEL with def<=0:");
for(const r of rows.filter(r=>r.sd!==null&&r.sd<=0).slice(0,40)) console.log(JSON.stringify(r));
' 2>&1 | head -60

